#include "../Source/PluginEditor.h"
#include "../Source/StudioRack.h"
#include <iostream>
#include <stdexcept>
namespace {
void need(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
void set(SpaceInfinityProcessor& p,const char* id,float value){auto* a=p.state.getParameter(id);need(a!=nullptr,"chorus/melt parameter exists");a->setValueNotifyingHost(a->convertTo0to1(value));}
std::array<double,3> chorusEnergy(float hz,int mode,float width,float tone){studio::DimensionChorus c;c.prepare(48000);c.configure(mode,width,tone,1);double mid=0,side=0,dry=0;for(int i=0;i<48000;++i){const float input=.2f*std::sin(float(juce::MathConstants<double>::twoPi*hz*i/48000));const auto out=c.process(input,input);need(std::isfinite(out[0])&&std::isfinite(out[1])&&std::abs(out[0])<.7&&std::abs(out[1])<.7,"bounded dimension output");if(i>12000){mid+=std::pow((out[0]+out[1])*.5,2);side+=std::pow((out[0]-out[1])*.5,2);dry+=input*input;}}return {mid,side,dry};}
std::vector<float> synth(bool two,float melt){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","distEnabled"})set(*p,id,0);set(*p,"engineMode",1);set(*p,"analogueCharacter",0);set(*p,"osc2Enabled",two?1:0);set(*p,"mix",two?.5f:0);set(*p,"wave",2);set(*p,"osc2Wave",2);set(*p,"osc1PhaseReset",1);set(*p,"osc2PhaseReset",1);set(*p,"osc2Semitone",7);set(*p,"routeA",0);set(*p,"routeB",0);set(*p,"noiseLevel",0);set(*p,"subLevel",0);set(*p,"attack",0);set(*p,"ampSustain",1);set(*p,"gain",.2f);set(*p,"oscMelt",melt);p->prepareToPlay(48000,128);juce::AudioBuffer<float> b(2,128);std::vector<float> result;for(int n=0;n<180;++n){juce::MidiBuffer midi;if(n==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p->processBlock(b,midi);for(int i=0;i<128;++i){const float v=b.getSample(0,i);need(std::isfinite(v)&&std::abs(v)<1,"melt synth finite with headroom");result.push_back(v);}}return result;}
std::vector<float> safety(int mode,float trim){
 auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);
 for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","distEnabled","osc2Enabled","analogueLabEnabled"})set(*p,id,0);
 set(*p,"routeA",0);set(*p,"wave",2);set(*p,"mix",0);set(*p,"noiseLevel",0);set(*p,"subLevel",0);set(*p,"analogueCharacter",0);set(*p,"osc1PhaseReset",1);set(*p,"ampSustain",1);set(*p,"attack",0);set(*p,"gain",.2f);set(*p,"presetTrim",trim);set(*p,"outputSafety",float(mode));p->prepareToPlay(48000,128);
 juce::AudioBuffer<float> audio(2,128);std::vector<float> values;
 for(int block=0;block<50;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,69,.9f),0);p->processBlock(audio,midi);for(int i=0;i<128;++i)values.push_back(audio.getSample(0,i));}return values;
}

void truePeakProtection(){
 for(double rate:{44100.,48000.,96000.}){
  infinity::TruePeakSafety safety;safety.prepare(rate,128);const int latency=safety.latencySamples();need(latency>int(rate*.001)&&latency<int(rate*.005),"peak safety latency must be short and reported");
  juce::dsp::Oversampling<float> meter(2,2,juce::dsp::Oversampling<float>::filterHalfBandFIREquiripple);meter.initProcessing(128);juce::AudioBuffer<float> audio(2,128);double peak=0,late=0,reference=0;
  const int samples=int(rate*.6);
  for(int pos=0;pos<samples;pos+=128){const int count=std::min(128,samples-pos);audio.setSize(2,count,false,false,true);
   for(int n=0;n<count;++n){const int t=pos+n;float x=t<int(rate*.1)?float(8*std::sin(juce::MathConstants<double>::twoPi*.41*t)+4*std::sin(juce::MathConstants<double>::twoPi*.13*t)):.1f*std::sin(float(juce::MathConstants<double>::twoPi*1000*t/rate));if(t<int(rate*.1)&&t%1009==0)x+=20;audio.setSample(0,n,x);audio.setSample(1,n,x*.375f);}
   safety.process(juce::dsp::AudioBlock<float>(audio),true);auto high=meter.processSamplesUp(juce::dsp::AudioBlock<const float>(audio));for(size_t c=0;c<high.getNumChannels();++c)for(size_t n=0;n<high.getNumSamples();++n)peak=std::max(peak,double(std::abs(high.getSample(int(c),int(n)))));
   for(int n=0;n<count;++n){const auto l=audio.getSample(0,n),r=audio.getSample(1,n);need(std::isfinite(l)&&std::isfinite(r)&&std::abs(r-l*.375f)<.000001,"peak protection must remain finite and stereo linked");if(pos+n>int(rate*.5)){const auto expected=.1*std::sin(juce::MathConstants<double>::twoPi*1000*(pos+n-latency)/rate);late+=l*l;reference+=expected*expected;}}
  }
  std::cout<<"Peak safety "<<rate<<" Hz: 4x peak "<<peak<<", recovered level "<<late/reference<<std::endl;need(peak<.995,"intersample overshoot on a hot signal");need(std::abs(late/reference-1)<.003,"peak safety leaves a persistent volume fade");
 }
}

}
int runChorusMeltSmoke(){try{
 truePeakProtection();
 const auto legacy=safety(0,0),clean=safety(1,0),hot=safety(1,24);double safetyDifference=0;
 for(size_t i=0;i<clean.size();++i){need(std::abs(legacy[i]-std::tanh(clean[i]))<.00005f,"legacy safety preserves its transfer while clean output is linear below knee");need(std::isfinite(hot[i])&&std::abs(hot[i])<=.990001f,"clean safety remains bounded under hot input");safetyDifference+=std::abs(legacy[i]-clean[i]);}need(safetyDifference>.01,"clean safety audibly preserves unsaturated low-level output");

 for(double rate:{44100.0,48000.0,96000.0})for(int mode=0;mode<4;++mode){studio::DimensionChorus c;c.prepare(rate);c.configure(mode,1.5f,.6f,.8f);for(int n=0;n<int(rate*.3);++n){const float x=.2f*std::sin(float(n)*.031f);const auto y=c.process(x,-x*.7f);need(std::isfinite(y[0])&&std::isfinite(y[1])&&std::abs(y[0])<.8&&std::abs(y[1])<.8,"all dimension voicings stable across sample rates");}c.configure(mode,1,.5f,0);for(int n=0;n<int(rate*.05);++n)c.process(.1f,-.2f);auto dry=c.process(.1f,-.2f);need(dry[0]==.1f&&dry[1]==-.2f,"zero chorus mix gives exact dry signal after smoothing");}
 for(int mode=0;mode<4;++mode){const auto wide=chorusEnergy(1000,mode,1,.6f),mono=chorusEnergy(1000,mode,0,.6f),bass=chorusEnergy(40,mode,1,.6f);need(wide[1]>wide[0]*.001,"each voicing creates stereo dimension from mono");need(mono[1]<1e-12,"width zero collapses the chorus spread");need(bass[0]>bass[2]*.7&&bass[0]<bass[2]*1.3&&bass[1]<bass[0]*.1,"dimension preserves bass weight and centre");std::cout<<"Dimension "<<mode<<" side/mid "<<wide[1]/wide[0]<<", bass level "<<bass[0]/bass[2]<<'\n';}
 auto dark=chorusEnergy(6000,2,1,0),bright=chorusEnergy(6000,2,1,1);need(bright[1]>dark[1]*2,"tone changes the audible chorus return");
 double interaction=0;for(int n=0;n<10000;++n){const float a=.2f*std::sin(n*.031f),b=.18f*std::sin(n*.047f);const auto neutral=studio::oscillatorMelt(a,b,0);need(neutral[0]==a&&neutral[1]==b,"melt zero is sample-exact bypass");const auto together=studio::oscillatorMelt(a+b,0,.8f),one=studio::oscillatorMelt(a,0,.8f),two=studio::oscillatorMelt(b,0,.8f);interaction+=std::abs(together[0]-one[0]-two[0]);}need(interaction>1,"melt creates shared harmonic interaction beyond a volume blend");
 need(synth(false,0)==synth(false,1),"melt leaves a single oscillator unchanged");auto raw=synth(true,0),melted=synth(true,.8f);double difference=0;for(size_t n=0;n<raw.size();++n)difference+=std::abs(raw[n]-melted[n]);need(difference>1,"MELT changes the actual two-oscillator output");
 auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);need(p->state.getRawParameterValue("chorusEngine")->load()==1,"Init offers new Dimension chorus");set(*p,"oscMelt",.7f);set(*p,"dimensionMode",3);set(*p,"dimensionWidth",1.2f);juce::MemoryBlock saved;p->getStateInformation(saved);auto recall=std::make_unique<SpaceInfinityProcessor>();recall->setStateInformation(saved.getData(),int(saved.getSize()));need(std::abs(recall->state.getRawParameterValue("oscMelt")->load()-.7f)<.0001&&recall->state.getRawParameterValue("dimensionMode")->load()==3,"melt and chorus recall");
 auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());for(auto size:{juce::Point<int>(800,760),{1000,790},{1180,820},{1500,950}}){editor->setSize(size.x,size.y);juce::Component* control=nullptr;for(auto* child:editor->getChildren())if(child->getName()=="Oscillator melt")control=child;need(control&&control->isVisible()&&editor->getLocalBounds().contains(control->getBounds()),"MELT fits on main at every size");}
 StudioRack rack(*p);rack.setLookAndFeel(&editor->getLookAndFeel());rack.setSize(900,1800);const auto folder=juce::File::getCurrentWorkingDirectory().getChildFile("audition");folder.createDirectory();auto file=folder.getChildFile("Dimension-Chorus.png");file.deleteFile();auto out=file.createOutputStream();need(out&&juce::PNGImageFormat{}.writeImageToStream(rack.module(4)->createComponentSnapshot(rack.module(4)->getLocalBounds(),true,1.5),*out),"actual dimension chorus screenshot");rack.setLookAndFeel(nullptr);
 // The researched airy pads also use Dimension on their sampled layers.
 for(int i=1;i<p->presetNames().size();++i){p->loadPreset(i);const auto category=p->presetCategory(i);const bool synth=p->state.getRawParameterValue("source")->load()==0;const float expectedMelt=synth&&category.contains("Leads")&&p->state.getRawParameterValue("osc2Enabled")->load()>.5f?.035f:0;const bool dimension=(synth&&category.contains("Pads"))||category=="Airy Pads";need(p->state.getRawParameterValue("chorusEngine")->load()==(dimension?1:0)&&std::abs(p->state.getRawParameterValue("oscMelt")->load()-expectedMelt)<.00001f,"reviewed factory chorus and oscillator settings recall");}
 std::cout<<"Dimension/Melt: stereo/mono/bass, tone, sample-rate stability, dry bypass, shared harmonics, one/two-oscillator audio, UI and recall passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Dimension/Melt: "<<e.what()<<'\n';return 183;}}
